qualified_questions.sparql_query:
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?player1 ?player2 ?character ?character2
WHERE {
    ?player1 a VideoGameOntology:Player .
    ?player1 VideoGameOntology:ownsCharacter ?character .
    ?player1 VideoGameOntology:isFriendWithPlayer ?player2 .
    OPTIONAL { 
        ?player2 VideoGameOntology:ownsCharacter ?character2 .
    }
    FILTER NOT EXISTS {
      ?player2 a VideoGameOntology:Player .
      FILTER NOT EXISTS {
        ?player2 VideoGameOntology:ownsCharacter ?character2 .
      }
    }
}

PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?player (COUNT(DISTINCT ?character) AS ?numCharacters) (COUNT(DISTINCT ?friend) AS ?numFriends)
WHERE {
    ?player rdf:type VideoGameOntology:Player .
    OPTIONAL { ?player VideoGameOntology:ownsCharacter ?character . }
    OPTIONAL { ?player VideoGameOntology:isFriendWithPlayer ?friend . }
}
GROUP BY ?player
ORDER BY ?numFriends

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX VideoGameOntology: <http://example.com/VideoGameOntology/>

SELECT ?game
WHERE {
    ?game rdf:type ?type .
    FILTER (?type = VideoGameOntology:Minigame || ?type = VideoGameOntology:Multiplayer || ?type = VideoGameOntology:SpecialPlayStyle || ?type = VideoGameOntology:Veteran || ?type = VideoGameOntology:Paragon || ?type = VideoGameOntology:Fandom || ?type = VideoGameOntology:Virtuosity || ?type = VideoGameOntology:Completion || ?type = VideoGameOntology:Luck)
    FILTER NOT EXISTS {
        ?game VideoGameOntology:hasMode VideoGameOntology:Tutorial
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX VideoGameOntology: <http://example.com/VideoGameOntology/>

SELECT ?player
WHERE {
    ?player rdf:type VideoGameOntology:Paragon .
    FILTER NOT EXISTS {
        ?player VideoGameOntology:Completion VideoGameOntology:HardMode .
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX VideoGameOntology: <http://example.com/VideoGameOntology/>

SELECT ?player
WHERE {
    ?player rdf:type VideoGameOntology:Paragon .
    FILTER NOT EXISTS {
        ?player VideoGameOntology:earns ?achievement .
        ?achievement rdfs:subClassOf* VideoGameOntology:Multiplayer .
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX VideoGameOntology: <http://example.com/VideoGameOntology/>

SELECT ?achievement
WHERE {
    ?achievement rdf:type ?type .
    ?type rdfs:subClassOf* VideoGameOntology:Achievement .
    FILTER NOT EXISTS {
        ?achievement rdfs:subClassOf ?task .
        ?task rdf:type VideoGameOntology:Completion .
    }
}

PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?playStyle ?achievement
WHERE {
    {
        ?playStyle rdf:type VideoGameOntology:SpecialPlayStyle .
        ?playStyle rdfs:subClassOf ?achievement .
    }
    UNION
    {
        ?playStyle rdf:type VideoGameOntology:Multiplayer .
        ?playStyle rdfs:subClassOf ?achievement .
    }
    FILTER (?achievement = VideoGameOntology:Achievement)
}

PREFIX VideoGameOntology: <http://video-game-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?x
WHERE {
    ?x rdfs:subClassOf* VideoGameOntology:Player .
    ?ownsAchievement rdf:type owl:ObjectProperty ;
                     rdfs:domain ?x ;
                     rdfs:range VideoGameOntology:Achievement .
    FILTER (?ownsAchievement = VideoGameOntology:ownsAchievement)
}

PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT (COUNT(DISTINCT ?player1) AS ?playersWithOfferingAndItem) (COUNT(DISTINCT ?player2) AS ?playersWithoutOffering)
WHERE {
    ?player1 rdf:type VideoGameOntology:Player .
    ?player1 VideoGameOntology:purchasesGameOffering ?gameProduct .
    ?character1 rdf:type VideoGameOntology:Character .
    ?character1 VideoGameOntology:ownsItem ?item .
    ?player1 VideoGameOntology:playsGame ?game .
    ?game VideoGameOntology:hasLeaderboard ?leaderboard .

    BIND(?player1 AS ?playerWithOfferingAndItem)

    {
        SELECT DISTINCT ?player2
        WHERE {
            ?player2 rdf:type VideoGameOntology:Player .
            FILTER NOT EXISTS {
                ?player2 VideoGameOntology:purchasesGameOffering ?gameProduct2 .
            }
        }
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX VideoGameOntology: <http://example.com/VideoGameOntology/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?property
WHERE {
    { 
        ?property rdfs:domain VideoGameOntology:Character .
        ?property rdf:type owl:ObjectProperty
    }
    UNION
    { 
        ?property rdfs:range VideoGameOntology:Character .
        ?property rdf:type owl:ObjectProperty
    }
    UNION
    { 
        ?property rdfs:domain VideoGameOntology:InstantaneousEvent .
        ?property rdf:type owl:ObjectProperty
    }
    UNION
    { 
        ?property rdfs:range VideoGameOntology:InstantaneousEvent .
        ?property rdf:type owl:ObjectProperty
    }
    UNION
    {
        ?property rdfs:domain VideoGameOntology:Player .
        ?property rdf:type owl:ObjectProperty
    }
    UNION
    {
        ?property rdfs:range VideoGameOntology:Player .
        ?property rdf:type owl:ObjectProperty
    }
    UNION
    {
        ?property rdfs:domain VideoGameOntology:Session .
        ?property rdf:type owl:ObjectProperty
    }
    UNION
    {
        ?property rdfs:range VideoGameOntology:Session .
        ?property rdf:type owl:ObjectProperty
    }
    UNION
    {
        ?property rdfs:domain VideoGameOntology:InstantaneousEvent .
        ?property rdfs:range VideoGameOntology:Character .
        ?property rdf:type owl:ObjectProperty
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX VideoGameOntology: <http://example.com/VideoGameOntology/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?username ?eventName
WHERE {
    { 
        ?player rdf:type VideoGameOntology:Player .
        ?player VideoGameOntology:username ?username .
        FILTER(isLiteral(?username))
    }
    UNION
    {
        ?event rdf:type VideoGameOntology:InstantaneousEvent .
        ?event VideoGameOntology:eventName ?eventName .
        FILTER(isLiteral(?eventName))
    }
}

PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?eventName ?username
WHERE {
    {
        ?event a VideoGameOntology:InstantaneousEvent .
        ?event VideoGameOntology:eventName ?eventName .
    }
    UNION
    {
        ?player a VideoGameOntology:Player .
        ?player VideoGameOntology:username ?username .
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX VideoGameOntology: <http://example.com/VideoGameOntology/>

SELECT ?property
WHERE {
    VALUES ?property { VideoGameOntology:releaseDate VideoGameOntology:eventTime VideoGameOntology:startTime VideoGameOntology:endTime }
    ?property a owl:DatatypeProperty .
}
